		templ_7745c5c3_Err = templruntime.WriteString(templ_7745c5c3_Buffer, 13, "<section id=\"rights\"><h2>9. ཁྱོད་ཀྱི་དབང་ཚད།</h2><p>GDPR གི་འོག་ལུ་ ཁྱོད་ཀྱི་སྒེར་གྱི་གནས་ཚུལ་གྱི་ཐད་ལས་ཁྱོད་ལུ་འོག་གི་དབང་ཚད་ཚུ་ཡོད།</p><ul><li><strong>འཛུལ་སྤྱོད།</strong> (དོན་ཚན་ 15) — ང་བཅས་ཀྱིས་ཁྱོད་ཀྱི་གནས་ཚུལ་ལག་ལེན་འཐབ་ཨིན་ན་ངེས་གཏན་བཟོ་ནི་དང་ དེའི་འདྲ་བཤུས།</li><li><strong>ཡང་དག་བཟོ་ནི།</strong> (དོན་ཚན་ 16) — ཡང་དག་མེན་པའམ་མ་ཚང་བའི་གནས་ཚུལ་ཡང་དག་བཟོ་ནི།</li><li><strong>བསུབ་ནི།</strong> (དོན་ཚན་ 17) — ཁྲིམས་ལུགས་ཀྱི་བསྐྱངས་ལུ་དམིགས་བསལ་ཚུ་ལུ་བརྟེན་ཁྱོད་ཀྱི་གནས་ཚུལ་བསུབ་ནི།</li><li><strong>ཚད་བཀག་ནི།</strong> (དོན་ཚན་ 18) — རྩོད་གཞི་ཅིག་ཐག་གཅོད་པའི་སྐབས་ལག་ལེན་མཚམས་འཇོག་ནི།</li><li><strong>འཁྱེར་འགྱོ་ཚུགས་པ།</strong> (དོན་ཚན་ 20) — ཁྱོད་ཀྱིས་བྱིན་མི་གནས་ཚུལ་གྱི་འཕྲུལ་ཆས་ཀྱིས་ལྷག་ཚུགས་པའི་ཕྱིར་འདྲེན།</li><li><strong>འགོག་པ།</strong> (དོན་ཚན་ 21) — ཁྲིམས་ལུགས་ཀྱི་ཕན་ཐོགས་ལུ་གཞི་བཞག་པའི་ལག་ལེན་ལུ། ང་བཅས་ཀྱིས་དབང་བའི་རྒྱུ་མཚན་སྟོན་མི་ཚུགས་པ་ཅིན་མཚམས་འཇོག།</li><li><strong>མོས་མཐུན་ཕྱིར་ལེན།</strong> (དོན་ཚན་ 7(3)) — མོས་མཐུན་ལུ་གཞི་བཞག་པའི་ལག་ལེན་ག་ཅི་ལུ་ཡང་ དཔེར་ན་ tafs ཨེཔ་ནང་ AI (རྩིས་ཐོ་ནང་ <a href=\"#ai-in-tafs\">གོང་</a> བཟུམ།)། ཕྱིར་ལེན་འདི་ཧེ་མའི་ཁྲིམས་ལུགས་ཀྱི་ལག་ལེན་ལུ་གནོད་མི་འདང་།</li></ul><p>དབང་ཚད་འདི་ཚུ་ག་ཅི་ལུ་ཡང་ལག་ལེན་འཐབ་ནི་ལུ་ <a href=\"mailto:privacy@kiff.dev\">privacy@kiff.dev</a> ལུ་གློག་འཕྲིན་གཏང་། ང་བཅས་ཀྱིས་དོན་ཚན་ 12(3) ལྟར་ དགོས་མེད་ཀྱི་ཕྱི་འགྱངས་མེད་པར་ ཟླ་བ་གཅིག་གི་ནང་ལན་འདེབས་འབདཝ་ཨིན། ཞུ་བ་འཛིང་ཅན་ཚུ་གི་དོན་ལུ་ཟླ་བ་གཉིས་ལུ་རིང་ཚད་བཟོ་ཚུགས་ཨིནམ་དང་ དེ་འབད་པ་ཅིན་ཁྱོད་ལུ་སླབ།</p><h3 id=\"export-chats\">ཁྱོད་རང་གི་ tafs གྲོས་ཚོགས།</h3><p>tafs ཨེཔ་ནང་ རྩིས་ཐོ་ → ངའི་གྲོས་ཚོགས་ཚུ་ཕྱིར་འདྲེན་འབད་ གིས་ taf རེ་རེ་དང་ Coach གི་བསྡོམས་ཁྱོད་རང་གི་གྲོས་ཚོགས། ཁྱོད་ཀྱིས་སྦྲགས་མི་ཡིག་ཆ་ཚུ་གི་མིང་དང་ཁྱོད་རང་གི་དྲན་ཐོ་ཚུ་ ལྷག་ཚུགས་པའི་ཡིག་ཆ་སྦེ་དང་ JSON སྦེ་ཕབ་ལེན་འབདཝ་ཨིན། དེ་ཚུ་ཕྱིར་འདྲེན་འབད་ཚུགས་མི་ཁྱོད་རང་རྐྱངམ་གཅིག། འཛིན་སྐྱོང་པ་ཡང་ན་རྩིས་ཐོའི་བདག་པོ་གིས་མི་ཚུགས། དང་ KIFF གི་རྩིས་ཐོ་ཕྱིར་འདྲེན་ནང་དེ་ཚུ་མི་ཚུད།</p><h3 id=\"delete-account\">ཁྱོད་ཀྱི་ tafs རྩིས་ཐོ་བསུབ་ནི།</h3><p>tafs འདི་ KIFF གི་ཨེཔ་ཨིན། ཁྱོད་ཀྱི་ tafs རྩིས་ཐོ་དང་དེའི་གནས་ཚུལ་བསུབ་ནི་ལུ།</p><ol><li>tafs ཨེཔ་ཁ་ཕྱེ་ཞིནམ་ལས་ནང་འཛུལ་འབད།</li><li>རྩིས་ཐོ་ལུ་འགྱོ་ དེ་ལས་ <em>རྩིས་ཐོ་བསུབ</em> ལུ་མཛུབ་བཙུགས།</li><li>ངེས་གཏན་བཟོ། རྩིས་ཐོ་ཅིག་བསུབ་པ་ལོག་སྟེ་མི་ཚུགས།</li></ol><p><em>རྩིས་ཐོ་བསུབ</em> འདི་ལས་ཁུངས་ཀྱི་རྩིས་ཐོ་བསུབ་ཆོག་མི་ལུ་ སྤྱིར་བཏང་དེའི་བདག་པོ་ལུ་སྟོན། ཁྱོད་ཀྱིས་དེ་མ་མཐོང་པ་ཡང་ན་ཨེཔ་མེད་པ་ཅིན་ ཁྱོད་ཀྱིས་ནང་འཛུལ་འབད་མི་ཁ་བྱང་ལས་ <a href=\"mailto:privacy@kiff.dev\">privacy@kiff.dev</a> ལུ་གློག་འཕྲིན་གཏང་ ཁྱོད་ཀྱི་གནས་ཚུལ་ང་བཅས་ཀྱིས་ དགོས་མེད་ཀྱི་ཕྱི་འགྱངས་མེད་པར་ ཟླ་བ་གཅིག་གི་ནང་བསུབ།</p><p>བསུབ་མི། རྩིས་ཐོའི་ལྡེ་མིག་འཕྲལ་དུ་མཚམས་འཇོག། དེའི་ tafs གྲོས་ཚོགས། དྲན་ཐོ། སྦྲགས་མི་ཡིག་ཆ་དང་མཐུད་མཚམས་ཚུ་འཕྲལ་དུ་བསུབ། དེ་ཚུའི་དུས་ཚོད་ཀྱི་འདྲ་བཤུས་ནང་ལས་ཉིནམ་ 35 གི་ནང་། རྩིས་ཐོའི་དོན་ལུ་ KIFF གིས་བཞག་མི་ཉིནམ་ 30 གི་ནང་བསུབ། དེ་ལས་ཟུར་བཞག་ནང་ལས་ཉིནམ་ 7 གི་ནང་། རྩིས་ཐོ་མིང་བཏོན་མི་ཞབས་ཏོག་ཐོ་བཀོད་ཉིནམ་ 30 གི་ནང་མེད་པར་འགྱོ། Tenant ཞིབ་འཇུག་གནས་ཚུལ་ tenant དང་བསུབ། གནས་ཚུལ་རིགས་རེ་རེའི་དོན་ལུ་ <a href=\"#retention\">བསྐྱངས།</a> ལུ་བལྟ།</p><p id=\"delete-data\">ཁྱོད་ཀྱི་གནས་ཚུལ་ཅུང་ཀུ་བསུབ་ཞིནམ་ལས་རྩིས་ཐོ་བཞག་ནི་ལུ། ཨེཔ་ནང་ གྲོས་ཚོགས་ཅིག་བསུབ་པ་ཅིན་དེའི་འཕྲིན་ཡིག་དང་སྦྲགས་མི་ཡིག་ཆ་དེ་དང་མཉམ་འགྱོ། taf ཅིག་རྩ་བསྐྲད་འབད་པ་ཅིན་དེའི་གྲོས་ཚོགས། དྲན་ཐོ་དང་མཐུད་མཚམས་ཚུ་དེ་དང་མཉམ་འགྱོ། གཞན་ག་ཅི་ལུ་ཡང་ <a href=\"mailto:privacy@kiff.dev\">privacy@kiff.dev</a> ལུ་གློག་འཕྲིན་གཏང་ཞིནམ་ལས་བསུབ་དགོ་མི་སླབ། ང་བཅས་ཀྱིས་ དགོས་མེད་ཀྱི་ཕྱི་འགྱངས་མེད་པར་ ཟླ་བ་གཅིག་གི་ནང་དེ་འབདཝ་ཨིན།</p><p>ཁྱོད་ལུ་ལྟ་རྟོག་འགོ་ཁྲིདཔ་ལུ་སྙན་ཞུ་འབད་ནིའི་དབང་ཚད་ཡོད། ང་བཅས་ཀྱི་གཙོ་འགོ་ལྟ་རྟོག་སྡེ་ཚན་འདི་ <a href=\"https://www.aki.ee/en\" target=\"_blank\" rel=\"noopener\">ཨེསྟོ་ནི་ཡ་གནས་ཚུལ་སྲུང་སྐྱོབ་ཞིབ་འཇུག་ལྷན་ཁག (Andmekaitse Inspektsioon)</a> ཨིན། ཁྱོད་ཀྱིས་ཁྱོད་སྡོད་ས་ཀྱི་ཚོགས་མི་རྒྱལ་ཁབ་ཀྱི་ལྟ་རྟོག་སྡེ་ཚན་ལུ་ཡང་སྙན་ཞུ་འབད་ཚུགས།</p><p><strong>ཁྱོད་ཀྱི་རྒྱལ་ཁབ།</strong> རྒྱལ་ཁབ་ལ་ལོ་ཅིག་གི་ཁྲིམས་གིས་སྲིད་བྱུས་འདི་གིས་སླབ་མི་ལས་ལྷག་པའི་དགོས་མཁོ་བཀོད། དེ་ཚུ་གིས་བསྣན་མི་ ཨིང་ཁ་དང་རྒྱལ་ཁབ་ཀྱི་སྐད་ཡིག་ནང་ <a href=\"/privacy/countries\">ཁྱོད་ཀྱི་རྒྱལ་ཁབ།</a> (ཨིང་ཁའི་ནང་) ནང་ཡོད།</p></section>")
